problems.solution:
def dropout(x, p, mask):
    return [v / (1 - p) if m else 0.0 for v, m in zip(x, mask)]

def dropout_eval(x):
    return list(x)

import numpy as np

def dropout_layer(X, p, rng, training=True):
    if not training:
        return X
    mask = rng.random(X.shape) >= p
    return X * mask / (1 - p)
